import re
from scripts.document import Document

doc = Document('unpacked')
ed = doc['word/document.xml']
W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

HEADLINE_RE = re.compile(r"^[A-Z0-9][A-Z0-9 .,:;'&()/%-]*$")

def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        if t.firstChild is not None:
            parts.append(t.firstChild.nodeValue)
    return ''.join(parts)

def add_underline(run):
    rprs = run.getElementsByTagName('w:rPr')
    rpr = rprs[0] if rprs else None
    if rpr is None:
        rpr = run.ownerDocument.createElementNS(W, 'w:rPr')
        run.insertBefore(rpr, run.firstChild)
    if rpr.getElementsByTagName('w:u'):
        return False
    u = run.ownerDocument.createElementNS(W, 'w:u')
    u.setAttributeNS(W, 'w:val', 'single')
    rpr.appendChild(u)
    return True

changed = 0
for p in ed.dom.getElementsByTagName('w:p'):
    text = para_text(p)
    if not text or not HEADLINE_RE.match(text):
        continue
    for r in p.getElementsByTagName('w:r'):
        if add_underline(r):
            changed += 1
    print('UNDERLINED HEADLINE:', repr(text))

print('runs underlined:', changed)
doc.save()
print('saved')

"""Underline all headline paragraphs in the unpacked quarterly_report.docx.

Headlines in this report are standalone all-caps section titles (no pStyle is
used in the document, so they are identified by content): a non-empty
paragraph whose text contains letters, has no lowercase letters (text equals
its own upper-case form), and is short (section-title length).  Body copy,
bullet lines, and table rows all contain lowercase text and are excluded.

For each such headline paragraph, every text run gets <w:u w:val="single"/>
inserted in its <w:rPr> (appended after sz/szCs, matching the schema order of
CT_RPr, where w:u follows w:sz-cs).
"""

try:
    from defusedxml import minidom
except ImportError:  # pragma: no cover - stdlib fallback
    from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
DOC_PATH = "unpacked/word/document.xml"


def paragraph_text(el):
    parts = []
    for t in el.getElementsByTagNameNS(W, "t"):
        if t.firstChild is not None:
            parts.append(t.firstChild.data)
    return "".join(parts)


def is_headline(el):
    text = paragraph_text(el).strip()
    if not text:
        return False
    if not any(ch.isalpha() for ch in text):
        return False
    if len(text) > 60:
        return False
    # Every letter is upper-case -> title-case / all-caps section headline.
    return text == text.upper()


def underline_run(run, doc):
    rprs = run.getElementsByTagNameNS(W, "rPr")
    if rprs:
        rpr = rprs[0]
    else:
        rpr = doc.createElementNS(W, "w:rPr")
        run.insertBefore(rpr, run.firstChild)
    us = rpr.getElementsByTagNameNS(W, "u")
    if us:
        us[0].setAttributeNS(W, "w:val", "single")
    else:
        u = doc.createElementNS(W, "w:u")
        u.setAttributeNS(W, "w:val", "single")
        rpr.appendChild(u)


def main():
    doc = minidom.parse(DOC_PATH)
    paragraphs = doc.getElementsByTagNameNS(W, "p")
    headline_texts = []
    underlined_runs = 0
    for p in paragraphs:
        if not is_headline(p):
            continue
        headline_texts.append(paragraph_text(p).strip())
        for r in p.getElementsByTagNameNS(W, "r"):
            underline_run(r, doc)
            underlined_runs += 1

    data = doc.toxml(encoding="utf-8")
    with open(DOC_PATH, "wb") as f:
        f.write(data)

    print("headlines underlined: %d" % len(headline_texts))
    print("runs underlined: %d" % underlined_runs)
    for t in headline_texts:
        print("- %s" % t)


if __name__ == "__main__":
    main()

